<?php
require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Response.php';require_once __DIR__.'/../lib/DocsRepository.php';Auth::requirePermission('docs.manage','edit');$pageTitle='دسته‌بندی مستندات';$adminExtraStylesheets=['/assets/css/workforce.css'];
if($_SERVER['REQUEST_METHOD']==='POST'){if(!Auth::verifyCsrf($_POST['csrf_token']??'')){flash('اعتبار درخواست منقضی شده است.','danger');redirect('/admin/docs-categories.php');}try{$id=(int)($_POST['id']??0);$title=trim((string)($_POST['title']??''));if($title==='')throw new InvalidArgumentException('عنوان دسته‌بندی الزامی است.');$slug=trim((string)($_POST['slug']??''));if($slug==='')$slug='doc-category-'.bin2hex(random_bytes(4));if(!preg_match('/^[a-z0-9_-]+$/i',$slug))throw new InvalidArgumentException('نامک فقط با حروف انگلیسی، عدد، خط تیره و زیرخط مجاز است.');$parent=(int)($_POST['parent_id']??0)?:null;if($id&&$parent===$id)throw new InvalidArgumentException('یک دسته نمی‌تواند والد خودش باشد.');$exists=Database::fetch('SELECT id FROM docs_categories WHERE slug=? AND id<>?',[$slug,$id]);if($exists)throw new InvalidArgumentException('این نامک قبلاً استفاده شده است.');$data=[$title,$slug,$parent,(int)($_POST['sort_order']??0),isset($_POST['active'])?1:0];if($id)Database::execute('UPDATE docs_categories SET title=?,slug=?,parent_id=?,sort_order=?,active=?,updated_at=NOW() WHERE id=?',[...$data,$id]);else Database::execute('INSERT INTO docs_categories(title,slug,parent_id,sort_order,active,created_at,updated_at) VALUES(?,?,?,?,?,NOW(),NOW())',$data);Auth::log((int)Auth::user()['id'],$id?'docs_category_updated':'docs_category_created','docs_categories',$id?:((int)Database::lastInsertId()));flash('دسته‌بندی ذخیره شد.');}catch(InvalidArgumentException $e){flash($e->getMessage(),'danger');}catch(Throwable $e){error_log('Docs category: '.$e->getMessage());flash('ذخیره دسته‌بندی انجام نشد.','danger');}redirect('/admin/docs-categories.php');}
$edit=isset($_GET['edit'])?Database::fetch('SELECT * FROM docs_categories WHERE id=?',[(int)$_GET['edit']]):null;$items=DocsRepository::categories();require __DIR__.'/../views/partials/admin-header.php';?>
<div class="workforce-head"><div><h1>دسته‌بندی مستندات</h1><p>ساختار آموزش‌ها و راهنماهای داخلی</p></div><a class="btn" href="/admin/docs.php">بازگشت به مستندات</a></div><nav class="workforce-tabs"><a href="/admin/docs.php">مستندات</a><a class="is-active" href="/admin/docs-categories.php">دسته‌بندی‌ها</a><a href="/admin/docs-view-logs.php">گزارش مطالعه</a></nav><div class="workforce-grid"><section class="card"><h2><?= $edit?'ویرایش دسته':'دسته جدید' ?></h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><label class="form-field"><span>عنوان</span><input name="title" value="<?=e($edit['title']??'')?>" required></label><label class="form-field"><span>نامک انگلیسی</span><input name="slug" dir="ltr" value="<?=e($edit['slug']??'')?>" placeholder="company-rules"></label><label class="form-field"><span>دسته والد</span><select name="parent_id"><option value="">بدون والد</option><?php foreach($items as $i):if((int)($edit['id']??0)===(int)$i['id'])continue;?><option value="<?=$i['id']?>" <?=(int)($edit['parent_id']??0)===(int)$i['id']?'selected':''?>><?=e($i['title'])?></option><?php endforeach?></select></label><label class="form-field"><span>ترتیب</span><input type="number" name="sort_order" value="<?=e($edit['sort_order']??0)?>"></label><label class="checkbox-item"><input type="checkbox" name="active" <?=!isset($edit['active'])||(int)$edit['active']?'checked':''?>> فعال</label><div class="form-actions"><button class="btn btn-primary">ذخیره</button><?php if($edit):?><a class="btn" href="/admin/docs-categories.php">انصراف</a><?php endif?></div></form></section><section class="card"><div class="table-wrap"><table><thead><tr><th>عنوان</th><th>والد</th><th>مطلب</th><th>وضعیت</th><th></th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=e($i['title'])?><small class="muted"><?=e($i['slug'])?></small></td><td><?=e($i['parent_title']?:'—')?></td><td><?=$i['article_count']?></td><td><?=(int)$i['active']?'فعال':'غیرفعال'?></td><td><a class="btn btn-small" href="?edit=<?=$i['id']?>">ویرایش</a></td></tr><?php endforeach?></tbody></table></div></section></div><?php require __DIR__.'/../views/partials/admin-footer.php';?>
